insert into cpl_memory (slug,kind,title,summary,tags,status,source,author,event_date) values
('d-curation-eta-net-pace-s661','decision','The Commons Curation ETA dates a reference only when its remaining work falls','commons_curation_eta.js (PR #3375): pace = net fall of a reference''s remaining work (universe less settled; new work counts against it) over 7 days, people''s share apart, from the new commons_history.json pairs series. Procedure chips = queue no_procedure blocks; people chips multiply people''s pace. No fall means Not dated yet, never an invented date.',array['commons','eta-clock','curation'],'proposed','SkyKnot (S661), on Sam''s ask in session','SkyKnot (S661)',date '2026-11-15'),
('d-framed-cobi-same-origin-only-s661','decision','COBI framed in COBI hides its chrome only inside a same-origin frame, and only reads the session','cobi_framed.js (PR #3373): ?framed=1 hides header and menu only in a same-origin frame (top level keeps them); cpl_session.js in such a frame hydrates once and never starts its refresh, so one keeper rotates the token; links to another tab open in the parent. Used for CPL Pathways in the CDC side panel.',array['commons','cdc','pathways','auth'],'proposed','SkyKnot (S661), COBIx review on #3373','SkyKnot (S661)',date '2026-11-15')
on conflict (slug) do nothing;
